// Generated by node scripts/build-sw.mjs. Do not edit the manifest by hand.
// Every precached response must match this release's SHA-256 before activation.
// A stale/mixed/failed deploy rejects installation and keeps the old worker.
const CACHE = __CACHE__;
const ASSETS = __ASSETS__;
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      for (const [path, expected] of ASSETS) {
        const canonical = new URL(path, self.registration.scope);
        const versioned = new URL(canonical);
        versioned.searchParams.set('v', CACHE);
        const response = await fetch(versioned, { cache: 'no-store' });
        if (!response.ok) throw new Error(`Asset unavailable: ${path}`);
        const bytes = await response.clone().arrayBuffer();
        const digest = await crypto.subtle.digest('SHA-256', bytes);
        const actual = Array.from(new Uint8Array(digest), x => x.toString(16).padStart(2, '0')).join('');
        if (actual !== expected) throw new Error(`Asset mismatch: ${path}`);
        await cache.put(canonical, response);
      }
      await self.skipWaiting();
    } catch (error) {
      await caches.delete(CACHE);
      throw error;
    }
  })());
});
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith('two-plates-') && k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});
// Water reminders sent by the scheduled Supabase job.
self.addEventListener('push', (e) => {
  let data = {};
  try { data = e.data ? e.data.json() : {}; } catch { /* no payload */ }
  e.waitUntil(self.registration.showNotification(data.title || 'Two Plates', {
    body: data.body || 'Time for some water',
    icon: 'icons/icon-192.png',
    badge: 'icons/icon-192.png',
    data: { url: './#today' },
  }));
});

self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  const url = e.notification.data?.url || './#today';
  e.waitUntil(clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {
    for (const c of list) { if ('focus' in c) { c.navigate(url); return c.focus(); } }
    return clients.openWindow(url);
  }));
});


self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== self.location.origin) return;
  // Only exact release assets are cache-first. Auth/API/unknown paths are
  // left to the network. Menu query parameters are read by the client.
  const relative = url.pathname.slice(new URL(self.registration.scope).pathname.length) || 'index.html';
  if (!ASSETS.some(([path]) => path === relative)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const canonical = new URL(relative, self.registration.scope);
    return await cache.match(canonical) || fetch(event.request);
  })());
});
